    "explanation": "정답 ④. Aspergilloma는 이미 형성된 폐 공동 안에서 자라는 균사 덩이이다. B의 당뇨·비안와 병변, 넓고 불규칙하며 격막이 드문 균사와 넓은 각도 분지는 털곰팡이증을 지지하고, 혈관벽 침범이 혈전·허혈성 괴사를 설명한다(PDF p.65–66, 69–70). ① 알레르기성 기관지폐 아스페르길루스증, aspergilloma, 침습성 감염을 구분해야 한다. B에는 실제 침습이 있다. ② A의 공동은 기존 결핵 병변이며, B의 혈전은 균사의 혈관 침범과 연결된다. ③ 침습성 Aspergillus도 혈관을 침범할 수 있으므로 혈관 침범만으로 균종을 확정하지 않는다. 균사의 형태와 임상 맥락을 함께 본다. ⑤ Candida는 출아효모·가성균사, Cryptococcus는 효모형 진균이며 바이러스 봉입체가 아니다. 털곰팡이 균사가 항상 무격막이거나 정확히 90도로만 분지한다는 뜻은 아니다.\n\n필기본 대조 보완: 아스페르길루스증의 세 양상인 알레르기성 기관지폐 반응(ABPA), 기존 공간의 균구(aspergilloma), 침습성 감염을 구별한다. 과민반응 중심의 ABPA나 공동 안 균사 덩이와 조직을 파고드는 침습성 감염은 병인이 다르다. 혈관 침범은 출혈·혈전·괴사를 설명하는 중요한 단서지만, 침습성 아스페르길루스증의 정의를 혈관 침범에만 한정하지 않는다. 균사의 형태, 실제 조직 침습과 위험 맥락을 함께 평가한다.\n\n통합실습 대조 보완: 균사가 절편에서 가로로 잘리면 둥근 구조로 보일 수 있으므로, 둥글다는 이유만으로 효모라고 판단하지 않는다. 겹치거나 접힌 균사에 생긴 선도 진짜 격막처럼 보일 수 있다. 여러 균사의 길이 방향 모습을 살펴 굵기와 균일성, 격막, 분지 형태를 함께 읽어야 하며, 분지각 하나만으로 Aspergillus와 Mucorales를 구분하지 않는다.",
