    "explanation": "정답 ①. A의 거품성 폐포 삼출물과 GMS 양성 낭벽은 Pneumocystis jirovecii 폐렴(PCP)에 맞는다(PDF p.73). GMS는 병원체의 낭벽을 보여 주며 감염된 폐세포의 핵을 염색하는 것이 아니다. B는 DAD(diffuse alveolar damage)이며 유리질막은 세포잔해·섬유소로 구성된다. DAD는 SARS 등에서 나타날 수 있지만 다른 원인의 DAD와 형태만으로 구별할 수 없다(p.18–21). ② CMV의 거대 핵내 봉입체와 낭벽·유리질막은 서로 다르다. ③ GMS는 항산염색이 아니며 DAD는 건락괴사 육아종이 아니다. ④ 코로나바이러스 감염에서는 병인특이적 봉입체가 없을 수 있으므로, 봉입체 부재로 감염을 배제하지 않는다. ⑤ A는 병원체 낭벽, B는 숙주 조직 손상에 따른 유리질막으로 서로 다른 수준의 증거이다. 이 설명은 코로나바이러스가 어떤 세포 변화도 일으키지 않는다는 뜻이 아니라, DAD가 병인특이적이지 않다는 뜻이다.\n\n필기본 대조 보완: 정상 폐포의 공기공간과, 손상된 폐포벽을 따라 세포잔해·섬유소가 분홍색 유리질막을 만드는 모습을 대비한다. A의 GMS 양성 낭벽은 병원체를 보여 주는 근거이고, B의 유리질막은 숙주 손상의 패턴이다. ARDS는 임상 증후군이고 DAD는 대표적인 병리 패턴이지만 모든 임상적 ARDS에서 DAD가 확인되는 것은 아니다. 또한 HIV 감염자의 폐렴을 모두 PCP로 단정하면 안 되며 일반 세균성 폐렴도 고려한다. PCP는 항암치료·스테로이드 등으로 면역이 저하된 HIV 비감염자에게도 발생할 수 있으므로, 위험군과 특징적 조직 소견을 함께 읽는다.\n\n통합실습 대조 보완: 조직절편에서는 거품성 삼출물이 폐포 공간을 채우는 위치를 확인하고, 기관지 세척 세포검체에서는 떨어져 나온 세포와 거품성 삼출물 덩어리를 살핀다. 이 덩어리를 GMS로 염색하면 둥근 낭벽과 컵·초승달 모양으로 허탈된 검은 낭벽이 드러날 수 있다. 단일 원형 구조만 보고 Cryptococcus로 단정하지 말고, 여러 낭벽의 형태와 삼출물 배경을 함께 해석한다.",
